  ('8e5101ad-5889-50f4-a974-5f0582ac2913', null, (select id from public.skills where slug = 'read-g12-argument-evidence'), null, 'medium',
   $q$Why does the historian include the fact that canal traffic held steady for four years after the railroad opened?$q$, $q$[{"text":"To prove that farmers in the valley disliked the railroad company.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To explain why the drought of the early 1850s finally came to an end.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To show the railroad's arrival did not trigger an immediate collapse.","is_correct":true},{"text":"To show that the railroad never took any trade away from the canal.","is_correct":false,"misconception_token":"overstates-text"}]$q$::jsonb, $q$To show the railroad's arrival did not trigger an immediate collapse.$q$, $q$If the railroad alone had emptied the canal, traffic would have fallen as soon as trains arrived, so steady traffic challenges that view. The historian later says rail did pull trade away by the late 1860s, so it did not take "no" trade.$q$, 'draft', 'f4ad9a65-95ad-5369-877f-e13cfb2ac73c')
