  ('faf39f46-f773-55ba-94cb-20e3bc431b94', null, (select id from public.skills where slug = 'read-g12-argument-evidence'), null, 'easy',
   $q$Which statement best expresses the author's claim?$q$, $q$[{"text":"Volunteer bird counts are as accurate as professional surveys.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"Biologists should stop counting common species like mallards.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Volunteer bird counts are too unreliable for serious research.","is_correct":false,"misconception_token":"reverses-claim"},{"text":"Volunteer counts are reliable for common birds but need help for rare ones.","is_correct":true}]$q$::jsonb, $q$Volunteer counts are reliable for common birds but need help for rare ones.$q$, $q$The first paragraph says volunteer counts "are trustworthy for common species, though they need professional support for rare ones." The claim is qualified, so saying they match professionals in every case overstates it.$q$, 'draft', '0418763f-6853-5233-9321-066a2c197ede')
